/* @lc app=leetcode id=3409 lang=kotlin */ class Solution { fun longestSubsequence(nums: IntArray): Int = nums.fold(Array(301) { IntArray(301) }) { g, x -> IntArray(301) { e -> listOf(x - e, x + e).filter { it in 0..300 && g[it][e] > 0 }.maxOfOrNull { g[it][e] + 1 } ?: 1 }.let { l -> l.reversed().runningFold(0) { m, v -> maxOf(m, v) }.drop(1).reversed().let { sm -> g.also { (0..300).forEach { d -> g[x][d] = maxOf(g[x][d], sm[d]) } } } } }.maxOf { it[0] } }